"""PLAN 2.8 (ruled 2026-10-31): GRAFCET charts are generated by tools/grafcet_from_st.py, never
hand-edited. A chart rebuilds byte for byte; every tag a chart names is declared in its OpenPLC
program; every chart carries the pending-review marker and the one-line footer only."""

from __future__ import annotations

import importlib.util
import re
import sys
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location(
    "grafcet_from_st", REPO / "tools" / "grafcet_from_st.py"
)
grafcet = importlib.util.module_from_spec(spec)
sys.modules["grafcet_from_st"] = grafcet  # dataclasses look their module up there
spec.loader.exec_module(grafcet)

TAG = re.compile(r"\b[A-Z][A-Z0-9_]*_(?:DI|DO|AI|AO)\b")


def test_the_sorter_chart_rebuilds_byte_for_byte(tmp_path):
    out = tmp_path / "sorting-by-height-grafcet.html"
    grafcet.write("sorting-by-height", out)
    kit = REPO / "kits" / "sorting-by-height" / "sorting-by-height-grafcet.html"
    assert out.read_bytes() == kit.read_bytes()


@pytest.mark.parametrize("scene", sorted(grafcet.SCENES))
def test_every_tag_in_a_chart_is_declared_in_its_program(scene):
    st = (REPO / "examples" / "openplc" / f"{scene}.st").read_text(encoding="utf-8")
    declared = set(re.findall(r"^\s*([A-Z][A-Z0-9_]+) AT %[IQ]", st, flags=re.MULTILINE))
    named = set(TAG.findall(grafcet.chart(scene)))
    assert named, scene
    assert named <= declared, sorted(named - declared)


@pytest.mark.parametrize("scene", sorted(grafcet.SCENES))
def test_marker_and_the_one_line_footer(scene):
    html = grafcet.chart(scene)
    assert "generated, pending PE review" in html[:300]
    assert (
        html.count(grafcet.FOOTER) == 1 and grafcet.FOOTER == "HIS Controls, OpenFactory, CC-BY-4.0"
    )
    assert not re.search(r"[\w.+-]+@[\w-]+\.[\w.]+", html)  # no email address
    for gone in ("Philippians", "HUNT INTEGRATIVE", "Rev:"):
        assert gone not in html, gone
    assert html == grafcet.chart(scene)  # deterministic
